import{_ as p,c as e,o as r,af as h}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"升","description":"高岛易断 - 升","frontmatter":{"title":"升","description":"高岛易断 - 升"},"headers":[],"relativePath":"zh/classics/takashima/046.md","filePath":"zh/classics/takashima/046.md"}'),i={name:"zh/classics/takashima/046.md"};function l(n,a,d,t,s,c){return r(),e("div",null,[...a[0]||(a[0]=[h('<h1 id="升" tabindex="-1">升 <a class="header-anchor" href="#升" aria-label="Permalink to “升”">​</a></h1><h2 id="升-1" tabindex="-1">升 <a class="header-anchor" href="#升-1" aria-label="Permalink to “升”">​</a></h2><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>升：元亨。用见大人，勿恤，南征吉。</p><h2 id="卦辞注" tabindex="-1">卦辞注 <a class="header-anchor" href="#卦辞注" aria-label="Permalink to “卦辞注”">​</a></h2><p>卦象由《巽》升《坤》，故曰《升》。《巽》本“小亨”，“元”者，《坤》之“元”，得夫坤元之气，故曰“元亨”。“大人”谓二，《巽》《传》曰“利见”，此曰“用见”，谓不升则不得见，用升而后可见也，故曰“用见”。得见大人，则大人必相与同升，自可无恤。“南征”者，出幽入明之谓也。《巽》之往《坤》，《坤》之往《巽》，皆必历于南，譬如日月之升，皆南征，而其降也，皆北行，故曰“南征吉”。</p><h2 id="象辞" tabindex="-1">象辞 <a class="header-anchor" href="#象辞" aria-label="Permalink to “象辞”">​</a></h2><p>地中生木，升。君子以顺德，积小以高大。</p><h2 id="象辞注" tabindex="-1">象辞注 <a class="header-anchor" href="#象辞注" aria-label="Permalink to “象辞注”">​</a></h2><p>地中生木，当其萌孽始生，藐乎小矣，及至蔽日干霄，其高大不可限量，盖不知几经岁月，得以积累而至此也。顺德以《坤》为极，《巽》柔在下，《坤》顺在上，由《巽》升《坤》，非积不能。君子法之，以顺其德，积小高大，德必日新而日懋也。人以此而树木者，君子即以此而树德焉。</p><h2 id="占断" tabindex="-1">占断 <a class="header-anchor" href="#占断" aria-label="Permalink to “占断”">​</a></h2><p>○　问时运：得春生之气，运途当日进日盛。</p><p>○　问功名：有指日高升之象。</p><p>○　问营商：积累锱铢，可渐成富饶巨室。</p><p>○　问战征：宜平地架列木梯，可以登高攻城。</p><p>○　问婚姻：顺为妇德，有以妾作嫡之象。</p><p>○　问家宅：此宅初时低小，近将改造大厦。</p><p>○　问疾病：是肝木春旺之症，若不顺气宽养，势将日积日重，颇为可危。</p><p>○　问货价：有逐步腾贵之象。</p><p>○　问秋收：风雨调顺，年谷丰登。</p><p>○　问行人：一路顺风，且积蓄颇丰。</p><p>○　问六甲：生女。</p><h2 id="初六解" tabindex="-1">初六解 <a class="header-anchor" href="#初六解" aria-label="Permalink to “初六解”">​</a></h2><p>初居《升》之始，为《巽》之主，《升》者下也，而允其升者上也，上允其升，则《升》之志遂矣。上互《震》，《震》雷出地，声闻百里，有《升》之象；下升上允，志同道合，吉莫大焉。《晋》六三曰“众允”，下为二阴所信；《升》初六曰“允升”，上为二阳所信。以阴信阴，悔亡而已，以阴信阳，乃得大吉。</p><h2 id="初六占" tabindex="-1">初六占 <a class="header-anchor" href="#初六占" aria-label="Permalink to “初六占”">​</a></h2><p>○　问时运：运途大顺，求名求利，无不如志，大吉。</p><p>○　问功名：一举成名，大吉。</p><p>○　问营商：货价高升，大可获利。</p><p>○　问战征：升高窥望，得识敌情，一战可得胜也，大吉。</p><p>○　问婚姻：两姓允合，大吉。</p><p>○　问家宅：有出谷迁乔之兆，吉。</p><p>○　问疾病：爻象本吉，于问病独非吉兆，惟在下痢下陷等症，则吉。</p><p>○　问讼事：宜上控，吉。</p><p>○　问六甲：生女。</p><h2 id="初六案例" tabindex="-1">初六案例 <a class="header-anchor" href="#初六案例" aria-label="Permalink to “初六案例”">​</a></h2><p>缙绅某来，请占气运，筮得《升》之《泰》。</p><p>断曰：卦象取“地中生木”，木得春气，枝叶怒生，渐增渐大，犹人行运得时，渐入佳境之象也。今占得初爻，是初运也。《升》者，自下升上，允者，我求而被允，《升》得其允，斯《升》之志遂，《升》之道行矣。运途得此，所求所谋，于名于利，无不“合志”，大吉之占也。</p><h2 id="九二解" tabindex="-1">九二解 <a class="header-anchor" href="#九二解" aria-label="Permalink to “九二解”">​</a></h2><p>二居《巽》之中，备刚中之德，即为“用见”之“大人”。初欲升五，必先历二，以求孚于二也。古者求贤审官，得人则告诸宗庙，二既孚初之《升》，特为斋祓以进之。上互《震》，《震》为祭，故“用禴”。《巽》，孟夏之月，“禴”，夏祭，“用禴”者，取“柔以时升”之义也。“禴”，祭之薄者，然输诚求升，虽薄亦孚，在诚不在物也，故“无咎”。《象传》曰“有喜”，即《彖传》所云“有庆”也。《萃》六二以柔应五之刚，《升》九二以刚应五之柔，其至诚感应，则一也，故爻象“用禴”同，“无咎”亦同。</p><h2 id="九二占" tabindex="-1">九二占 <a class="header-anchor" href="#九二占" aria-label="Permalink to “九二占”">​</a></h2><p>○　问时运：运途得中，必有喜事临门。</p><p>○　问营商：商业全凭信实，有信卖买进出，无诈无虞，自能永远，且可获利。</p><p>○　问功名：定有泥金报喜。</p><p>○　问战征：出师必祭，信为兵家之要，得信则三军一心，无战不克矣。</p><p>○　问婚姻：二五交孚，阴阳合德，大喜。</p><p>○　问家宅：主有喜兆。</p><p>○　问疾病：宜祷。</p><p>○　问六甲：单月生男，双月生女。</p><h2 id="九二案例" tabindex="-1">九二案例 <a class="header-anchor" href="#九二案例" aria-label="Permalink to “九二案例”">​</a></h2><p>友人某来，请占气运，筮得《升》之《谦》。</p><p>断曰：《升》者自下升上，有积小高大之象。今足下问气运，占得第二爻，二爻刚中，为卦中之大人。“孚”者，信也，得其信，不特上下交通，即鬼神亦能感格。爻象如此，知足下信谊素著，于朋友上下之间，无不交孚，故得“无咎”，且近日即有升腾喜兆。</p><p>明治二十九年，某贵显来，为设立农工银行，占问成否，筮得《升》之《谦》。</p><p>断曰：卦体《坤》上《巽》下，《坤》为财，为富，《巽》为商，为利。五行以我克者为财，《巽》木克《坤》土，土为财。《升》者，积小高大，有渐进渐长之象。今贵下占问银行生业，得第二爻，爻辞曰“孚”，孚者，信也，金银贸易，最要在信。“利用”者，利于用也，《洪范·六府》“心曰利用”，即此旨也。据此爻辞，银行必成，且有喜兆。</p><h2 id="九三解" tabindex="-1">九三解 <a class="header-anchor" href="#九三解" aria-label="Permalink to “九三解”">​</a></h2><p>《升》之三，《巽》之终，《坤》之始也，《坤》为虚，亦为邑，故曰“升虚邑”。《说文》：“虚，大邱。九夫为井，四井为邑，四邑为邱”。邱，谓之虚，《诗》“升彼虚矣”，虚，即墟也。墟为空旷高地，由井升邑，由邑升虚，可见“积小以高大”，历试诸艰，胜任愉快，地日辟而日大，位日进而日高。《象传》曰“无所疑”，信乎三之《升》，《升》之得其任矣。征诸太王居岐，一年成邑，二年成都，三年五倍于初，爻所言升虚升邑，盖谓此也。《升》卦爻象三、四、五三爻，皆隐指周室之事。</p><h2 id="九三占" tabindex="-1">九三占 <a class="header-anchor" href="#九三占" aria-label="Permalink to “九三占”">​</a></h2><p>○　问时运：目下运途恰好，渐进渐盛。</p><p>○　问营商：市廛谓之趁虚，言就虚地，会集货物而成市邑，可见商业日盛也。</p><p>○　问功名：《升》本发达之象，初方“允”，二则“孚”，至三则已升而在上，可无疑也。</p><p>○　问战征：经此兵燹，城邑空虚，“升虚邑”，夺取空城矣。</p><p>○　问家宅：有前空虚，后富实之象。</p><p>○　问婚姻：“虚邑”，犹空房也，不吉。</p><p>○　问疾病：必是虚弱之症无疑。</p><p>○　问失物：不得。</p><p>○　问六甲：九三阳爻，生男。</p><h2 id="九三案例" tabindex="-1">九三案例 <a class="header-anchor" href="#九三案例" aria-label="Permalink to “九三案例”">​</a></h2><p>明治十六年，缙绅某任某县令，将赴任，请占任事吉凶，筮得《升》之《师》。</p><p>断曰：“虚邑”，为凋敝之地，人烟寥落，治理殊难，非盘根错节之才，未易胜任也。今贵下新授某邑知事，行将赴任，占得此爻，以贵下练达之才，任此积衰之邑，必能治剧理繁，为人所难为，当有措之裕如，无容疑也。可为贵下信之矣。</p><p>明治廿八年五月，为开垦北海道十胜国利别原野，占其成否，筮得《升》之《师》。</p><p>断曰：爻辞与占象，悉相符合，可谓深切详明。曰“虚邑”，即荒土地，曰“升虚邑”，是辟荒土而成村落也。初则允其升，谓从事开垦者，志相合也；二则孚其升，谓从事开垦者，必“有喜”也；三则升已成矣。事虽难，可无疑也，其成必矣。</p><p>明治三十一年，占司法省气运，筮得《升》之《师》。</p><p>断曰：《象》谓积小高大，凡风化之日趋日上，政教之日进日强，皆为《升》也。今占司法省，欲改设公明之法律，为内地杂居之准备，得《升》卦三爻。夫有其邑而不治，谓之“虚邑”，有其法而不用，亦谓之虚法。兹者司法省，新颁法律，将实施之于内地，是升虚而作实也，此令一行，必无阻碍，无容疑虑焉。</p><h2 id="六四解" tabindex="-1">六四解 <a class="header-anchor" href="#六四解" aria-label="Permalink to “六四解”">​</a></h2><p>岐山为周发祥之地，太王迁之，文王康之，时告祭乔狱，岐山当必在其内也。盖天子祭天地，诸侯祭其境内之山川。“亨于岐山”，岐山在周境内，周先王实主其祀焉。称王者，追王之谓也。迁岐山之始，避狄而来，而积小高大，遂成为王业之基，吉何如也！《象传》以“顺事”释之，盖隐指文王服事之诚，有顺德，无二心也。此周公不言之旨，合前后爻象观之，而可知矣。</p><h2 id="六四占" tabindex="-1">六四占 <a class="header-anchor" href="#六四占" aria-label="Permalink to “六四占”">​</a></h2><p>○　问时运：事顺适，吉而无咎。</p><p>○　问战征：古者祷战，祈克于上帝，然后接敌，此即用享之义也。享而后战，其必克矣，吉。</p><p>○　问营商：货物之生也，多取于山林川谷之间。祭法，民之取财用者，必祭之。谓祭之可获利也。吉。</p><p>○　问功名：“亨于岐山”，易侯而王，大吉之兆。</p><p>○　问家宅：宜祭告宅神，吉。</p><p>○　问疾病：宜祷。</p><p>○　问六甲：生女。</p><h2 id="六四案例" tabindex="-1">六四案例 <a class="header-anchor" href="#六四案例" aria-label="Permalink to “六四案例”">​</a></h2><p>某商人来，请占气运，筮得《升》之《恒》。</p><p>断曰：《升》卦诸爻，皆言升，惟二四不言升，其义并取于祭享，谓人欲升腾发达，必先求神明之保也。四爻辞曰，“王用亨于岐山”，岐山为太王避狄之地，浸炽浸昌，大启尔宇，为周室王运发祥之始。今足下占得此爻，知足下气运通顺，正如晓日东升，逐步增高，财运亨通，其中虽由足下计划之精，要亦有神助也。宜斋祓以祷之，吉。</p><h2 id="六五解" tabindex="-1">六五解 <a class="header-anchor" href="#六五解" aria-label="Permalink to “六五解”">​</a></h2><p>五以《坤》德居中，位极其尊，《象传》所称“君子以顺德，积小以高大”，惟五当之。“阶”，天子之阼阶也，升之于阶，尊之至焉。然不正则为新莽，为曹操，其何能吉？古来必如大舜之有鳏在下，侧陋明扬，以至命陟帝位，爻曰“贞吉”，《象》曰“大得志”，惟舜有之矣。而作《易》之旨，则隐指西伯方百里起，终受周命之事也。</p><h2 id="六五占" tabindex="-1">六五占 <a class="header-anchor" href="#六五占" aria-label="Permalink to “六五占”">​</a></h2><p>○　问时运：平生志愿，无不得遂，大吉之兆。</p><p>○　问功名：拾级而登，荣宠已极。</p><p>○　问营商：五为中数，凡营财之道，不宜过盈，以得中为吉，故曰“贞吉”。</p><p>○　问战征：凡攻城，必用梯阶，所以升高也。城必可克，故吉。</p><p>○　问婚姻：五与二相应，爻曰“升阶”，有攀结高亲之象，故二曰“有喜”。</p><p>○　问疾病：《升》，增也，病不宜升，乱阶厉阶，皆非吉兆。</p><p>○　问讼事：讼本凶事，是谓祸阶，升阶则讼愈凶，何以得吉？</p><p>○　问失物：当就阶墀间寻之。</p><p>○　问六甲：生女。</p><h2 id="六五案例" tabindex="-1">六五案例 <a class="header-anchor" href="#六五案例" aria-label="Permalink to “六五案例”">​</a></h2><p>某氏来，请占其女气运，筮得《升》之《井》。</p><p>断曰：《升》者谓“柔以时升”，《升》得其时，是以吉也。人之气运，亦以时行，得时则顺，失时则逆，惟在当其可之谓时也。今足下占问子女行运，想必为嫁娶之事也。《诗》咏迨吉，为婚姻之及时。阶，上进也，“升阶”，升而愈上也，是必有贵戚订姻，上嫁之象，大吉。后闻此女，果嫁某缙绅。</p><h2 id="上六解" tabindex="-1">上六解 <a class="header-anchor" href="#上六解" aria-label="Permalink to “上六解”">​</a></h2><p>上居《坤》之极，《升》至于上，《升》无可升矣。如日之升，朝而日出，昼而日中，暮而日入，“冥”，则昏暮也，《坤》为冥，故曰“冥升”。“不息”者，昼夜循环之谓也，今日月没，明日复升，故曰“利于不息之贞”。《坤》曰“永贞”，即“不息之贞”也。在人之升，至上则禄位已尽，魂升魄散，归入幽冥之域，凡生前富贵利达，消归无有，惟此道德勋名，足以流传于不息耳，故《象传》以“消不富”释之，此之谓也。</p><h2 id="上六占" tabindex="-1">上六占 <a class="header-anchor" href="#上六占" aria-label="Permalink to “上六占”">​</a></h2><p>○　问时运：好运已过，且待后运重来，可以得利。</p><p>○　问战征：有率军夜进，误入幽谷之象，利于息，待天明可出险也。</p><p>○　问营商：防有人财两失之患。</p><p>○　问功名：《升》至于上，功名已显，防身后萧条。</p><p>○　问婚姻：恐不得偕老。</p><p>○　问家宅：宅运已过，势必中落。</p><p>○　问疾病：大象不利，“冥升”者，魂升于天也。</p><p>○　问六甲：生女，恐不育。</p><h2 id="上六案例" tabindex="-1">上六案例 <a class="header-anchor" href="#上六案例" aria-label="Permalink to “上六案例”">​</a></h2><p>明治二十四年，占国运，筮得《升》之《蛊》。</p><p>断曰：论卦体，《坤》上《巽》下，由《巽》升《坤》，《升》至于六，《坤》位已终，无可再升矣。今占国运，得《升》上爻，我国家自维新以来，一革旧政，悉效欧美之法，以为取彼之长，补我之短，以冀日进于富强也。当时使年轻子弟，游学欧美，以习学其文学言语、政化风俗，三年学成归国，即升为学士、博士之职，使之教授国内子弟。法非不善，意非不良，无如此辈游学子弟，其于我国向时政教，本未谙练，即于外国教育，亦徒窥其皮毛，反以扬扬自得，蔑视老成。其间所谓进步者，如海军陆军，骏骏日上，亦自有可取，而极之教育之原，身心之本，终觉利不胜害，为可慨也。维新迄今，已二十余年，《升》进地步，约计已到上爻。“冥升”者，为日已近暮，无可复升，其利在“不息之贞”。“不息”者，为去而复来，循环不息之谓也。盖谓我国治运所关，凡新法之不善者，皆当反我旧政，以返为《升》，犹是日之没而复升，晦而复明，即所谓“不息之贞也”。斯之谓“利”，斯之谓“贞”。</p>',114)])])}const m=p(i,[["render",l]]);export{b as __pageData,m as default};
